      "ls -U /proc/<pid>/fd | wc -l",
      "ls -l /proc/<pid>/fd | head -50",
      "readlink /proc/<pid>/fd/<fd>",
      "lsof -nP -p <pid>",
      "lsof +L1",
      "ss -tanp | grep 'pid=<pid>'",
